let data=load(),lang=localStorage.getItem('brc_lang')||'en',unit='MM',mode='od',filter='all',selectedId='',last=null,currentUserId=sessionStorage.getItem('brc_user')||'',adminUntil=Number(sessionStorage.getItem('brc_admin_until')||0),memory=0,memorySet=false,memoryExpanded=false,memoryUserCollapsed=false,calcExpr='0',calcFreshInput=false;
function load(){try{const d=JSON.parse(localStorage.getItem(KEY)||'null')||structuredClone(defaults);d.settings={...defaults.settings,...d.settings};d.backups=Array.isArray(d.backups)?d.backups:[];d.calcHistory=Array.isArray(d.calcHistory)?d.calcHistory:[];d.convHistory=Array.isArray(d.convHistory)?d.convHistory:[];d.users=(d.users||[]).map(u=>{const migratedPin=u.role==='admin'&&u.name==='Raymond'&&u.pin==='0000'?'0921':u.pin;return {...u,pin:migratedPin,permissions:u.role==='admin'?{editBelt:true,addBelt:true,deleteBelt:true}:{editBelt:false,addBelt:false,deleteBelt:false,...u.permissions}}});return d}catch{return {...structuredClone(defaults),calcHistory:[]}}}
function save(inventoryChanged=false){localStorage.setItem(KEY,JSON.stringify(data));if(inventoryChanged&&data.settings.autoBackup&&data.settings.backupFrequency==='onChange')createInternalBackup('inventory-change');if(inventoryChanged){window.BRCCloud?.markDirty?.();void window.BRCCloud?.syncFromLocal(data)?.catch?.(()=>{})}}
const cloudConfigured=()=>!!window.BRCCloud?.configured?.(),cloudProfile=()=>window.BRCCloud?.state?.profile||null,cloudUser=()=>window.BRCCloud?.state?.user||null,cloudOnline=()=>window.BRCCloud?.state?.status==='connected';
const localUser=()=>data.users.find(x=>x.id===currentUserId);
const user=()=>{const p=cloudProfile(),u=cloudUser();return p?{id:p.id,name:p.display_name||u?.email||'Cloud User',email:u?.email||'',role:p.role,cloud:true}:localUser()};
const isAdmin=()=>user()?.role==='admin';
const can=p=>cloudProfile()?!!window.BRCCloud?.can?.(p):(isAdmin()||!!localUser()?.permissions?.[p]);
const actorName=()=>user()?.name||tr('guest');
const tr=k=>T[lang]?.[k]||T.en[k]||k,fmt=n=>Number.isFinite(n)?Number(n).toLocaleString(undefined,{maximumFractionDigits:3}):'—',uid=p=>`${p}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),1800)}
function btn(text,fn,cls=''){const b=document.createElement('button');b.textContent=text;b.className=cls;b.onclick=fn;return b}
function stackField(label,input){const l=document.createElement('label');l.textContent=label;l.append(input);return l}
function openModal(title,body,actions=[],topActions=[]){$('modalTitle').textContent=title;$('modalBody').replaceChildren(body);$('modalActions').replaceChildren(...actions);$('modalTopActions').replaceChildren(...topActions);$('modal').querySelector('.dialog')?.classList.toggle('sticky-editor',topActions.length>0);$('modal').classList.add('open');setTimeout(()=>($('modalBody').querySelector('input,select,textarea')||$('modalTopActions').querySelector('.primary')||$('modalActions').querySelector('.primary'))?.focus(),0)}
function closeModal(){$('modal').classList.remove('open');$('modal').querySelector('.dialog')?.classList.remove('sticky-editor')}
function authValid(){return isAdmin()&&Date.now()<adminUntil}
function unlock(){const mins=Number(data.settings.adminTimeoutMinutes)||0;adminUntil=mins?Date.now()+mins*60000:Date.now()+1500;sessionStorage.setItem('brc_admin_until',String(adminUntil));updateAuthStatus()}
function lockAdmin(){adminUntil=0;sessionStorage.removeItem('brc_admin_until');updateAuthStatus()}
async function deviceAuth(){if(!window.PublicKeyCredential||!data.settings.deviceCredentialId)throw 0;const challenge=crypto.getRandomValues(new Uint8Array(32));await navigator.credentials.get({publicKey:{challenge,timeout:60000,userVerification:'required'}});unlock()}
async function inventoryAuth(force=false){
 if(!force&&!data.settings.passwordProtection)return true;
 if(!cloudProfile()){return new Promise(resolve=>adminAuth(()=>resolve(true)))}
 return new Promise(resolve=>{const overlay=document.createElement('div');overlay.className='verify-overlay';const dialog=document.createElement('div');dialog.className='verify-dialog';const title=document.createElement('h2');title.textContent=lang==='zh'?'库存验证':'Inventory Verification';const label=document.createElement('label');label.textContent=lang==='zh'?'库存修改密码':'Inventory Password';const p=document.createElement('input');p.type='password';p.inputMode='numeric';p.autocomplete='off';const error=document.createElement('div');error.className='verify-error';error.hidden=true;const showError=msg=>{error.textContent=msg;error.hidden=false;p.classList.add('invalid');p.select();p.focus()};const actions=document.createElement('div');actions.className='actions';let done=false;const finish=v=>{if(done)return;done=true;overlay.remove();resolve(v)};const cancel=btn(tr('cancel'),()=>finish(false));const confirmBtn=btn(lang==='zh'?'确认':'Confirm',async()=>{error.hidden=true;p.classList.remove('invalid');try{const ok=await window.BRCCloud.verifyInventoryPin(p.value);if(ok===null)return showError(lang==='zh'?'尚未设置库存修改密码。请先在“设置”中建立，或由管理员在“用户”页面重设。':'Inventory password has not been set. Set it in Settings or ask an administrator to reset it from Users.');if(!ok)return showError(lang==='zh'?'库存修改密码错误，请重新输入。':'Incorrect inventory password. Please try again.');finish(true)}catch(e){showError(e?.message||String(e))}},'primary');actions.append(cancel,confirmBtn);label.append(p);dialog.append(title,label,error,actions);overlay.append(dialog);document.body.append(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay)finish(false)});p.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();e.stopPropagation();confirmBtn.click()}else if(e.key==='Escape'){e.preventDefault();e.stopPropagation();finish(false)}});setTimeout(()=>p.focus(),0)})
}
function changeInventoryPin(){
 if(!cloudProfile())return toast(lang==='zh'?'请先登录云端账号。':'Cloud sign-in required.');const wrap=document.createElement('div'),p1=document.createElement('input'),p2=document.createElement('input');wrap.className='form-stack';p1.type=p2.type='password';p1.inputMode=p2.inputMode='numeric';wrap.append(stackField(lang==='zh'?'新库存密码':'New Inventory Password',p1),stackField(lang==='zh'?'确认库存密码':'Confirm Inventory Password',p2));openModal(lang==='zh'?'修改库存密码':'Change Inventory Password',wrap,[btn(tr('cancel'),closeModal),btn(tr('save'),async()=>{if(p1.value!==p2.value)return toast(lang==='zh'?'两次密码输入不一致。':'Passwords do not match.');if(!/^\d{4,}$/.test(p1.value))return toast(lang==='zh'?'库存密码必须至少 4 位数字。':'Inventory password must contain at least 4 digits.');try{await window.BRCCloud.setInventoryPin(p1.value);closeModal();toast(tr('saved'))}catch(e){toast(e.message)}},'primary')])
}
function adminAuth(done){if(cloudProfile()){if(!isAdmin())return toast(tr('adminRequired'));return done()}if(!isAdmin())return toast(tr('adminRequired'));if(authValid())return done();const wrap=document.createElement('div');wrap.className='form-stack';const p=document.createElement('input');p.type='password';p.maxLength=4;wrap.append(stackField(tr('adminPin'),p));const actions=[];if(data.settings.deviceCredentialId)actions.push(btn(tr('useDeviceUnlock'),async()=>{try{await deviceAuth();closeModal();done()}catch{toast(tr('deviceUnlockFailed'))}}));actions.push(btn(tr('cancel'),closeModal),btn(tr('login'),()=>{const a=data.users.find(x=>x.role==='admin');if(!a||p.value!==a.pin)return toast(tr('wrongPin'));unlock();closeModal();done()},'primary'));openModal(tr('adminPin'),wrap,actions)}
