function setResults(){const v=last?.ok?last:{};$('valMM').textContent=fmt(v.lengthMm);$('valM').textContent=fmt(v.lengthM);$('valIN').textContent=fmt(v.lengthIn);$('valFT').textContent=fmt(v.lengthFt);$('valYD').textContent=fmt(v.lengthYd);$('turnsVal').textContent=fmt(v.turns);$('odResultVal').textContent=Number.isFinite(v.outsideDiameterMm)?`${fmt(unit==='MM'?v.outsideDiameterMm:v.outsideDiameterMm/25.4)} ${unit==='MM'?'mm':'in'}`:'—'}
