function renderSettings(){$('protectionToggle').textContent=data.settings.passwordProtection?tr('on'):tr('off');$('protectionToggle').className='toggle-button '+(data.settings.passwordProtection?'on':'off');$('adminTimeoutSelect').value=['0','1','5','10','15','30'].includes(String(data.settings.adminTimeoutMinutes))?String(data.settings.adminTimeoutMinutes):'custom';$('deviceUnlockBtn').textContent=data.settings.deviceCredentialId?tr('disableDeviceUnlock'):tr('enableDeviceUnlock');$('autoBackupToggle').textContent=data.settings.autoBackup?tr('on'):tr('off');$('autoBackupToggle').className='toggle-button '+(data.settings.autoBackup?'on':'off');$('backupSchedule').style.opacity=data.settings.autoBackup?'1':'.5';$('lastBackup').textContent=data.settings.lastBackup?new Date(data.settings.lastBackup).toLocaleString():'—';$('nextBackup').textContent=nextBackupText();$('backupDestinationNote').textContent=lang==='zh'?'自动备份保存在 BRC 内部。使用“导出”可生成 PDF、Excel、TXT，或可恢复的 BRC JSON 备份。':lang==='es'?'Las copias automáticas se guardan dentro de BRC. Use Exportar para crear PDF, Excel, TXT o una copia JSON restaurable.':'Automatic backups stay inside BRC. Use Export to create PDF, Excel, TXT, or a restorable BRC JSON backup.';updateAuthStatus();$('backupInventory').checked=data.settings.backupInventory!==false;$('backupSettings').checked=data.settings.backupSettings!==false;renderBackupHistory();updateAuthStatus()}
function populateBackupControls(){const f=$('backupFrequency');f.innerHTML=['daily','weekly','monthly','onClose','onChange'].map(v=>`<option value="${v}">${tr(v)}</option>`).join('');f.value=data.settings.backupFrequency;const days=['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];$('backupDay').innerHTML=days.map((v,i)=>`<option value="${i}">${tr(v)}</option>`).join('');$('backupDay').value=data.settings.backupDay;$('backupDate').innerHTML=Array.from({length:31},(_,i)=>`<option value="${i+1}">${i+1}</option>`).join('');$('backupDate').value=data.settings.backupDate;$('backupTime').value=data.settings.backupTime;$('backupRetention').value=data.settings.backupRetention;updateScheduleVisibility()}
function updateScheduleVisibility(){const f=$('backupFrequency').value;$('backupDayLabel').style.display=$('backupDay').style.display=f==='weekly'?'':'none';$('backupDateLabel').style.display=$('backupDate').style.display=f==='monthly'?'':'none';$('backupTimeLabel').style.display=$('backupTime').style.display=['daily','weekly','monthly'].includes(f)?'':'none'}
function backupPayload(type){const now=new Date().toISOString();if(type==='inventory')return{product:'Belt Roll Calculator',type:'inventory',build:BUILD,created:now,data:{belts:structuredClone(data.belts),history:structuredClone(data.history)}};return{product:'Belt Roll Calculator',type:'settings',build:BUILD,created:now,data:{users:structuredClone(data.users),settings:structuredClone(data.settings),calcHistory:structuredClone(data.calcHistory||[]),convHistory:structuredClone(data.convHistory||[])}}}
function canBackup(){return cloudProfile()?window.BRCCloud?.can?.('backup')!==false:true}
function canRestoreBackup(){return cloudProfile()?!!window.BRCCloud?.can?.('restoreBackup'):isAdmin()}
function createInternalBackup(reason='manual',types=null){try{const selected=types||[data.settings.backupInventory!==false?'inventory':null,data.settings.backupSettings!==false?'settings':null].filter(Boolean);if(!selected.length)return toast(lang==='zh'?'请至少选择一种备份。':'Select at least one backup type.');const snaps=selected.map(type=>{const payload=backupPayload(type),snap={id:uid('backup'),date:payload.created,reason,type,payload};data.backups.push(snap);return snap});const keep=Math.max(1,Number(data.settings.backupRetention)||30);if(data.backups.length>keep*2)data.backups=data.backups.slice(-(keep*2));data.settings.lastBackup=snaps[snaps.length-1].date;data.history.push({id:uid('tx'),date:new Date().toISOString(),belt:'System',action:'backup-'+reason,user:user()?.name||tr('guest'),note:selected.join(', '),protected:true});localStorage.setItem(KEY,JSON.stringify(data));renderSettings();renderBackupHistory();renderHistory();return snaps}catch(e){console.error(e);toast(lang==='zh'?'备份失败。':'Backup failed.');return null}}
function backupBlob(payload){return new Blob([JSON.stringify(payload,null,2)],{type:'application/json'})}
function download(name,text,type){const blob=text instanceof Blob?text:new Blob([text],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(url)},1500)}
function exportSnapshots(snaps){(snaps||[]).forEach(s=>download(`BRC_${s.type==='inventory'?'Inventory':'Settings'}_${s.date.replace(/[:T]/g,'-').slice(0,16)}.json`,backupBlob(s.payload),'application/json'))}
function exportInventoryRows(){return (data.belts||[]).map(x=>({Name:x.name||'',PartNumber:x.part||'',Manufacturer:x.manufacturer||'',Width_mm:Number(x.width)||0,Thickness_mm:Number(x.thickness)||0,Color:x.color||'',Application:x.application||'',CoreDiameter_mm:Number(x.coreDiameter)||0,Stock_m:Number(x.stock)||0,MinimumStock_m:Number(x.minStock)||0,Location:x.location||'',Notes:x.notes||'',Modified:x.modified||''}))}
function exportHistoryRows(){return (data.history||[]).map(x=>({Transaction:x.id||'',Date:x.date||'',Belt:x.belt||'',Part:x.part||'',Action:x.action||'',Amount:x.amount??'',Before:x.before??'',After:x.after??'',User:x.user||'',Notes:x.note||''}))}
function exportText(){const lines=['Belt Roll Calculator','Build '+BUILD,'Exported: '+new Date().toISOString(),'','INVENTORY'];for(const r of exportInventoryRows())lines.push(Object.entries(r).map(([k,v])=>`${k}: ${v}`).join(' | '));lines.push('','HISTORY');for(const r of exportHistoryRows())lines.push(Object.entries(r).map(([k,v])=>`${k}: ${v}`).join(' | '));download(`BRC_Export_${new Date().toISOString().slice(0,10)}.txt`,'\ufeff'+lines.join('\n'),'text/plain;charset=utf-8')}
async function exportExcel(){try{const XLSX=await import('https://cdn.jsdelivr.net/npm/xlsx@0.18.5/+esm');const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(exportInventoryRows()),'Inventory');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(exportHistoryRows()),'History');XLSX.writeFile(wb,`BRC_Export_${new Date().toISOString().slice(0,10)}.xlsx`)}catch(e){console.error(e);toast(lang==='zh'?'Excel 导出组件加载失败，请检查网络连接。':'Excel export component could not load. Check your connection.')}}
async function exportPdf(){try{const [{jsPDF},html2canvasMod]=await Promise.all([import('https://cdn.jsdelivr.net/npm/jspdf@2.5.2/+esm'),import('https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/+esm')]);const html2canvas=html2canvasMod.default||html2canvasMod;const report=document.createElement('div');report.className='export-report';report.innerHTML=`<h1>Belt Roll Calculator</h1><p>Build ${esc(BUILD)} · ${esc(new Date().toLocaleString())}</p><h2>Inventory</h2><table><thead><tr><th>Name</th><th>PN</th><th>Width</th><th>Thickness</th><th>Stock</th><th>Location</th></tr></thead><tbody>${(data.belts||[]).map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.part)}</td><td>${fmt(x.width)} mm</td><td>${fmt(x.thickness)} mm</td><td>${fmt(x.stock)} m</td><td>${esc(x.location||'')}</td></tr>`).join('')}</tbody></table><h2>History</h2>${(data.history||[]).slice(-100).reverse().map(x=>`<p><b>${esc(x.belt||'System')}</b> · ${esc(x.action||'')} · ${esc(new Date(x.date).toLocaleString())}<br><small>${esc(x.note||'')}</small></p>`).join('')}`;document.body.appendChild(report);const canvas=await html2canvas(report,{scale:1.5,backgroundColor:'#ffffff'});report.remove();const pdf=new jsPDF({orientation:'portrait',unit:'pt',format:'a4'}),pw=pdf.internal.pageSize.getWidth(),ph=pdf.internal.pageSize.getHeight(),margin=24,imgW=pw-margin*2,imgH=canvas.height*imgW/canvas.width;const img=canvas.toDataURL('image/jpeg',.92);let y=margin;pdf.addImage(img,'JPEG',margin,y,imgW,imgH);let remaining=imgH-(ph-margin*2);while(remaining>0){pdf.addPage();y=margin-(imgH-remaining);pdf.addImage(img,'JPEG',margin,y,imgW,imgH);remaining-=ph-margin*2}pdf.save(`BRC_Export_${new Date().toISOString().slice(0,10)}.pdf`)}catch(e){console.error(e);document.querySelector('.export-report')?.remove();toast(lang==='zh'?'PDF 导出组件加载失败，请检查网络连接。':'PDF export component could not load. Check your connection.')}}
function downloadBackup(){const snaps=createInternalBackup('export');if(!snaps)return;exportSnapshots(snaps);toast(tr('backupComplete'))}
function exportDataMenu(){const wrap=document.createElement('div');wrap.className='export-format-grid';const option=(title,desc,fn)=>{const b=btn(title,()=>{closeModal();void fn()});b.innerHTML=`<b>${title}</b><small>${desc}</small>`;return b};wrap.append(option(tr('exportPdf'),lang==='zh'?'适合查看、打印和存档。':'For viewing, printing and archiving.',exportPdf),option(tr('exportExcel'),lang==='zh'?'库存与历史记录分工作表。':'Inventory and History worksheets.',exportExcel),option(tr('exportTxt'),lang==='zh'?'轻量纯文本导出。':'Lightweight plain-text export.',exportText),option(tr('exportJson'),lang==='zh'?'可用于恢复 BRC 数据。':'Restorable BRC backup.',downloadBackup));openModal(tr('exportFormat'),wrap,[btn(tr('cancel'),closeModal)])}
async function importBackup(f){try{const j=JSON.parse(await f.text());if(j.type==='inventory'){if(!Array.isArray(j.data?.belts)||!Array.isArray(j.data?.history))throw 0;data.belts=j.data.belts;data.history=j.data.history}else if(j.type==='settings'){if(!Array.isArray(j.data?.users)||!j.data?.settings)throw 0;data.users=j.data.users;data.settings={...defaults.settings,...j.data.settings};data.calcHistory=j.data.calcHistory||[];data.convHistory=j.data.convHistory||[]}else{const d=j.data||j;if(!Array.isArray(d.users)||!Array.isArray(d.belts))throw 0;data={...structuredClone(defaults),...d,settings:{...defaults.settings,...d.settings}}}localStorage.setItem(KEY,JSON.stringify(data));renderAll();toast(tr('backupImported'))}catch(e){console.error(e);toast(tr('invalidBackup'))}}
function restoreBackup(id){const snap=data.backups.find(x=>x.id===id);if(!snap)return;if(!canRestoreBackup())return toast(lang==='zh'?'没有恢复备份权限。':'Restore backup permission required.');adminAuth(()=>{if(!confirm(lang==='zh'?`恢复此${snap.type==='inventory'?'库存':'设定'}备份？当前资料会先自动备份。`:'Restore this backup? Current data will be backed up first.'))return;createInternalBackup('before-restore',[snap.type]);const d=snap.payload.data;if(snap.type==='inventory'){data.belts=structuredClone(d.belts);data.history=structuredClone(d.history)}else{data.users=structuredClone(d.users);data.settings={...defaults.settings,...structuredClone(d.settings)};data.calcHistory=structuredClone(d.calcHistory||[]);data.convHistory=structuredClone(d.convHistory||[])}save();renderAll();toast(tr('backupImported'))})}
function renderBackupHistory(){const box=$('backupHistoryList');if(!box)return;$('backupHistoryHeading').textContent=tr('backupHistory');box.innerHTML=(data.backups||[]).slice().reverse().map(s=>`<div class="backup-record"><div><b>${tr(s.type==='inventory'?'inventoryBackup':'settingsBackup')}</b><small>${new Date(s.date).toLocaleString()} · ${esc(s.reason)}</small><small>Build ${esc(s.payload.build||BUILD)}</small></div><div class="actions">${canBackup()?`<button data-export-snap="${s.id}">${tr('exportBackup')}</button>`:''}${canRestoreBackup()?`<button class="primary" data-restore-snap="${s.id}">${tr('restore')}</button>`:''}</div></div>`).join('')||`<div class="muted">${tr('empty')}</div>`;document.querySelectorAll('[data-export-snap]').forEach(b=>b.onclick=()=>{const s=data.backups.find(x=>x.id===b.dataset.exportSnap);exportSnapshots([s])});document.querySelectorAll('[data-restore-snap]').forEach(b=>b.onclick=()=>restoreBackup(b.dataset.restoreSnap))}
function nextBackupText(){if(!data.settings.autoBackup)return '—';const f=data.settings.backupFrequency;if(f==='onChange')return tr('waitingChange');if(f==='onClose')return tr('onCloseText');const n=nextScheduledDate();return n?n.toLocaleString():'—'}
function nextScheduledDate(){const [h,m]=(data.settings.backupTime||'00:00').split(':').map(Number),now=new Date(),d=new Date(now);d.setSeconds(0,0);d.setHours(h,m,0,0);if(data.settings.backupFrequency==='daily'){if(d<=now)d.setDate(d.getDate()+1)}else if(data.settings.backupFrequency==='weekly'){let add=(Number(data.settings.backupDay)-d.getDay()+7)%7;if(add===0&&d<=now)add=7;d.setDate(d.getDate()+add)}else if(data.settings.backupFrequency==='monthly'){d.setDate(Math.min(Number(data.settings.backupDate),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));if(d<=now){d.setMonth(d.getMonth()+1,1);d.setDate(Math.min(Number(data.settings.backupDate),new Date(d.getFullYear(),d.getMonth()+1,0).getDate()))}}return d}
function checkScheduledBackup(){if(!data.settings.autoBackup||!['daily','weekly','monthly'].includes(data.settings.backupFrequency))return;const last=data.settings.lastBackup?new Date(data.settings.lastBackup):new Date(0),next=nextScheduledDate();const due=new Date(next);if(next>Date.now())due.setDate(due.getDate()-(data.settings.backupFrequency==='daily'?1:data.settings.backupFrequency==='weekly'?7:0));if(data.settings.backupFrequency==='monthly')due.setMonth(due.getMonth()-1);if(last<due)createInternalBackup('scheduled')}

