function renderFAQ(){const title=$('faqTitle'),list=$('faqList');if(!title||!list)return;title.textContent=lang==='zh'?'帮助与常见问题':lang==='es'?'Ayuda y preguntas frecuentes':'Help & FAQ';list.innerHTML=(FAQ[lang]||FAQ.en).map(([q,a])=>`<details><summary>${esc(q)}</summary><p>${esc(a)}</p></details>`).join('')}

