let compoundMode='fraction',compoundOutputMode='fraction';
const compoundDenominators=[2,4,8,16,32,64];
function parseCompoundNumber(value){const n=Number(String(value??'').trim().replace(',','.'));return Number.isFinite(n)?n:0}
function compoundFractionParts(){return {numerator:$('compoundNumerator').value,denominator:$('compoundDenominator').value}}
function compoundTotalInches(){const f=compoundFractionParts();return compoundImperialToInches({feet:parseCompoundNumber($('compoundFeet').value),inches:parseCompoundNumber($('compoundInches').value),numerator:f.numerator,denominator:f.denominator,mode:compoundMode})}
function normalizeCompound(totalInches,mode=compoundMode){return inchesToCompoundImperial(totalInches,mode,64)}
function splitFractionText(text){const m=String(text||'').match(/^(\d+)\/(\d+)$/);return m?{numerator:m[1],denominator:m[2]}:{numerator:'',denominator:'16'}}
function populateNumeratorOptions(denominator,selected=''){
 const d=Number(denominator)||16,s=$('compoundNumerator');
 s.innerHTML=['',...Array.from({length:Math.max(0,d-1)},(_,i)=>String(i+1))].map(v=>`<option value="${v}">${v||'—'}</option>`).join('');
 s.value=selected&&Number(selected)<d?String(selected):'';
}
function populateFractionPair(fraction=''){
 const parts=splitFractionText(fraction),den=$('compoundDenominator');
 den.innerHTML=compoundDenominators.map(v=>`<option value="${v}">${v}</option>`).join('');
 den.value=compoundDenominators.includes(Number(parts.denominator))?String(parts.denominator):'16';
 populateNumeratorOptions(den.value,parts.numerator);
}
function setCompoundFromTotalInches(totalInches,mode=compoundMode){
 const v=normalizeCompound(totalInches,mode);
 $('compoundFeet').value=Number.isFinite(v.feet)?v.feet:'';
 $('compoundInches').value=Number.isFinite(v.inches)?String(v.inches):'';
 if(mode==='fraction')populateFractionPair(v.fraction||'');
 updateCompoundSummary();
}
function formatFeetInches(totalInches,mode='fraction'){const v=normalizeCompound(totalInches,mode);if(mode==='decimal')return `${v.feet} ft ${Number(v.inches.toFixed(6))} in`;return `${v.feet} ft ${v.inches}${v.fraction?` ${v.fraction}`:''} in`}
function updateCompoundSummary(){const box=$('compoundSummary');if(!box)return;const total=compoundTotalInches();box.textContent=Number.isFinite(total)&&total>=0?`${formatFeetInches(total,compoundMode)}  (= ${Number(total.toFixed(6))} in)`:''}
function setCompoundMode(mode){
 const total=compoundTotalInches();
 compoundMode=mode==='decimal'?'decimal':'fraction';
 $('compoundFractionMode').classList.toggle('active',compoundMode==='fraction');
 $('compoundDecimalMode').classList.toggle('active',compoundMode==='decimal');
 $('compoundFractionField').hidden=compoundMode==='decimal';
 $('compoundInches').inputMode=compoundMode==='decimal'?'decimal':'numeric';
 setCompoundFromTotalInches(total,compoundMode);
 convert(false);
}
function updateCompoundLabels(){const t=compoundText[lang]||compoundText.en;$('compoundInputTitle').textContent=t.title;$('compoundFeetLabel').textContent=t.feet;$('compoundInchesLabel').textContent=t.inches;$('compoundFractionLabel').textContent=t.fraction;$('compoundNumeratorLabel').textContent=t.numerator;$('compoundDenominatorLabel').textContent=t.denominator;$('compoundNumerator').setAttribute('aria-label',t.numerator);$('compoundDenominator').setAttribute('aria-label',t.denominator);$('compoundFractionMode').textContent=t.fractionMode;$('compoundDecimalMode').textContent=t.decimalMode;$('compoundOutputLabel').textContent=compoundOutputText[lang]||compoundOutputText.en;$('outputFractionMode').textContent=t.fractionMode;$('outputDecimalMode').textContent=t.decimalMode}
function updateCompoundVisibility(){const active=$('convCategory').value==='length'&&$('convFrom').value==='ft+in';$('compoundLengthInput').hidden=!active;$('convInput').hidden=active;$('convFromRow').classList.toggle('compound-active',active);if(active)updateCompoundSummary();const toCompound=$('convCategory').value==='length'&&$('convTo').value==='ft+in';$('convToValue').classList.toggle('compound-output',toCompound);$('compoundOutputMode').hidden=!toCompound;updateCompoundOutputButtons()}
function updateCompoundOutputButtons(){$('outputFractionMode').classList.toggle('active',compoundOutputMode==='fraction');$('outputDecimalMode').classList.toggle('active',compoundOutputMode==='decimal')}
function setCompoundOutputMode(mode){compoundOutputMode=mode==='decimal'?'decimal':'fraction';updateCompoundOutputButtons();convert(false)}
function setupCompoundLength(){
 populateFractionPair();updateCompoundLabels();
 $('compoundFractionMode').onclick=()=>setCompoundMode('fraction');
 $('compoundDecimalMode').onclick=()=>setCompoundMode('decimal');
 $('outputFractionMode').onclick=()=>setCompoundOutputMode('fraction');
 $('outputDecimalMode').onclick=()=>setCompoundOutputMode('decimal');
 ['compoundFeet','compoundInches'].forEach(id=>{$(id).oninput=()=>{updateCompoundSummary();convert(false)};$(id).onchange=()=>convert(true)});
 $('compoundDenominator').onchange=()=>{const current=$('compoundNumerator').value;populateNumeratorOptions($('compoundDenominator').value,current);updateCompoundSummary();convert(true)};
 $('compoundNumerator').onchange=()=>{updateCompoundSummary();convert(true)};
}
function populateConverterUnits({reset=false}={}){const cat=$('convCategory').value||'length',def=conv[cat]||conv.length,units=Object.keys(def.units),prevFrom=$('convFrom').value,prevTo=$('convTo').value;$('convFrom').innerHTML=units.map(u=>`<option value="${esc(u)}">${esc(unitLabel(u))}</option>`).join('');$('convTo').innerHTML=units.map(u=>`<option value="${esc(u)}">${esc(unitLabel(u))}</option>`).join('');if(!reset&&units.includes(prevFrom))$('convFrom').value=prevFrom;else $('convFrom').selectedIndex=0;if(!reset&&units.includes(prevTo)&&prevTo!==$('convFrom').value)$('convTo').value=prevTo;else $('convTo').selectedIndex=Math.min(1,units.length-1);updateCompoundVisibility();convert(false)}
function populateConverters(){const c=$('convCategory'),old=c.value||'length',labels=convLabels[lang]||convLabels.en;c.innerHTML=Object.keys(conv).map(k=>`<option value="${k}">${labels[k]}</option>`).join('');c.value=conv[old]?old:'length';updateCompoundLabels();populateConverterUnits({reset:false});renderConvHistory()}
function setupConverterEvents(){const category=$('convCategory'),from=$('convFrom'),to=$('convTo'),input=$('convInput'),clear=$('convClear'),swap=$('convSwap'),clearHistory=$('clearConvHistory');category.onchange=()=>{populateConverterUnits({reset:true});renderConvHistory()};from.onchange=()=>{updateCompoundVisibility();convert(true)};to.onchange=()=>{updateCompoundVisibility();convert(true)};input.oninput=()=>convert(false);input.onchange=()=>convert(true);clear.onclick=()=>{input.value='';$('compoundFeet').value='';$('compoundInches').value='';populateFractionPair();updateCompoundSummary();convert(false)};swap.onclick=swapConverterUnits;clearHistory.onclick=()=>{data.convHistory=[];save();renderConvHistory()}}
function setupCalculatorControls(){const standard=$('calcStandardMode'),scientific=$('calcScientificMode'),angle=$('angleMode'),clearHistory=$('clearCalcHistory'),memoryToggle=$('calcMemoryToggle');standard.onclick=()=>{calcMode='standard';setupDeskCalc()};scientific.onclick=()=>{calcMode='scientific';setupDeskCalc()};angle.onclick=()=>{angleUnit=angleUnit==='DEG'?'RAD':'DEG';setupDeskCalc()};clearHistory.onclick=()=>{data.calcHistory=[];save();renderCalcHistory()};memoryToggle.onclick=toggleMemoryDisplay}
function convert(record=false){const cat=$('convCategory').value,a=$('convFrom').value,b=$('convTo').value;let n=a==='ft+in'&&cat==='length'?compoundTotalInches():+$('convInput').value;if(!Number.isFinite(n)){ $('convToValue').value='—';$('convOutput').textContent='';return }let out,inputDisplay='',outputDisplay='';if(cat==='length'&&a==='ft+in'){const meters=n*.0254;if(b==='ft+in')out=n;else out=meters/conv.length.units[b];inputDisplay=formatFeetInches(n,compoundMode)}else if(cat==='length'&&b==='ft+in'){const meters=n*conv.length.units[a];out=meters/.0254;outputDisplay=formatFeetInches(out,compoundOutputMode)}else out=convertEngineeringValue(n,cat,a,b);if(cat==='length'&&b==='ft+in'){$('convToValue').value=outputDisplay;$('convOutput').textContent=`${fmt(out)} in`}else{$('convToValue').value=fmt(out);$('convOutput').textContent=cat==='length'&&b==='ft'?`${Math.floor(out)} ft ${fmt((out-Math.floor(out))*12)} in`:''}if(record){data.convHistory=data.convHistory||[];data.convHistory.push({date:new Date().toISOString(),cat,from:a,to:b,input:n,output:out,inputDisplay,outputDisplay});data.convHistory=data.convHistory.slice(-100);save();renderConvHistory()}}
function swapConverterUnits(){const a=$('convFrom').value,b=$('convTo').value;if($('convCategory').value==='length'&&(a==='ft+in'||b==='ft+in')){const totalMeters=a==='ft+in'?compoundTotalInches()*.0254:(Number($('convInput').value)||0)*conv.length.units[a];if(a==='ft+in')compoundOutputMode=compoundMode;if(b==='ft+in')compoundMode=compoundOutputMode;$('convFrom').value=b;$('convTo').value=a;updateCompoundVisibility();if(b==='ft+in')setCompoundFromTotalInches(totalMeters/.0254,compoundMode);else $('convInput').value=fmt(totalMeters/conv.length.units[b]).replaceAll(',','');convert(true);return}$('convFrom').value=b;$('convTo').value=a;convert(true)}
function renderConvHistory(){const box=$('convHistoryList');if(!box)return;$('convHistoryTitle').textContent=tr('conversionHistory');$('clearConvHistory').textContent=tr('clear');box.innerHTML=(data.convHistory||[]).slice().reverse().map((x,i)=>`<button class="calc-history-item" data-conv-history="${data.convHistory.length-1-i}"><span>${esc(x.inputDisplay||`${fmt(x.input)} ${unitLabel(x.from)}`)} → ${esc(x.outputDisplay||`${fmt(x.output)} ${unitLabel(x.to)}`)}</span><b>${convLabels[lang]?.[x.cat]||x.cat}</b></button>`).join('')||`<div class="muted">${tr('empty')}</div>`;document.querySelectorAll('[data-conv-history]').forEach(b=>b.onclick=()=>{const x=data.convHistory[+b.dataset.convHistory];$('convCategory').value=x.cat;populateConverterUnits({reset:true});$('convFrom').value=x.from;$('convTo').value=x.to;updateCompoundVisibility();if(x.from==='ft+in')setCompoundFromTotalInches(x.input,compoundMode);else $('convInput').value=x.input;convert(false)})}
let calcMode='standard',angleUnit='DEG';
function calculatorKeys(){
 if(calcMode==='scientific')return [
  ['MC','MR','M+','M-','(',')'],
  ['2nd','π','e','CE','C','⌫'],
  ['sin','cos','tan','√','x²','÷'],
  ['asin','acos','atan','ln','log','×'],
  ['7','8','9','xʸ','10ˣ','−'],
  ['4','5','6','1/x','n!','+'],
  ['1','2','3','+/−','%','='],
  ['0','0','.','EXP','Ans','=']
 ];
 return [
  ['MC','MR','M+','M-'],
  ['CE','C','⌫','÷'],
  ['7','8','9','×'],
  ['4','5','6','−'],
  ['1','2','3','+'],
  ['+/−','0','.','=']
 ];
}
function memoryText(){return lang==='zh'?'记忆':lang==='es'?'Memoria':'Memory'}
function renderMemoryDisplay(){const toggle=$('calcMemoryToggle'),row=$('calcMemoryRow'),label=$('calcMemoryLabel'),value=$('calcMemoryValue');if(!toggle||!row)return;toggle.textContent=memoryExpanded?'M ▾':'M ▸';toggle.classList.toggle('has-memory',memorySet);toggle.setAttribute('aria-expanded',String(memoryExpanded));toggle.title=memoryExpanded?(lang==='zh'?'收起记忆显示':lang==='es'?'Ocultar memoria':'Hide memory'):(lang==='zh'?'展开记忆显示':lang==='es'?'Mostrar memoria':'Show memory');row.hidden=!memoryExpanded;label.textContent=memoryText();value.textContent=memorySet?fmt(memory):'—'}
function toggleMemoryDisplay(){memoryExpanded=!memoryExpanded;memoryUserCollapsed=!memoryExpanded;renderMemoryDisplay()}
function setupDeskCalc(){
 const rows=calculatorKeys();
 $('calcKeys').className=`calc-keys ${calcMode==='scientific'?'scientific':''}`;
 $('calcKeys').innerHTML=rows.flatMap((row,ri)=>row.map((k,ci)=>{
  const cls=[k==='='?'primary':'',calcMode==='scientific'&&ri===7&&ci===0?'zero-wide':'',calcMode==='scientific'&&ri===7&&ci===1?'duplicate-zero':''].filter(Boolean).join(' ');
  return `<button data-key="${k}" class="${cls}">${k}</button>`
 })).join('');
 document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>deskKey(b.dataset.key));
 $('calcStandardMode').classList.toggle('active',calcMode==='standard');
 $('calcScientificMode').classList.toggle('active',calcMode==='scientific');
 $('angleMode').hidden=calcMode!=='scientific';
 $('angleMode').textContent=angleUnit;
 $('calculatorModeTitle').textContent=tr(calcMode==='standard'?'standardCalculator':'scientificMode');
 $('calcStandardMode').textContent=tr('standardMode');
 $('calcScientificMode').textContent=tr('scientificMode');
 $('calcHistoryTitle').textContent=tr('calculationHistory');
 $('clearCalcHistory').textContent=tr('clear');
 renderCalcHistory();renderMemoryDisplay()
}
function renderCalcHistory(){const box=$('calcHistoryList');if(!box)return;box.innerHTML=(data.calcHistory||[]).slice().reverse().map((x,i)=>`<button class="calc-history-item" data-ch="${data.calcHistory.length-1-i}"><span>${esc(x.expression)}</span><b>${esc(x.result)}</b></button>`).join('')||`<div class="muted">${tr('empty')}</div>`;document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>{calcExpr=data.calcHistory[+b.dataset.ch].result;calcFreshInput=true;$('deskDisplay').textContent=calcExpr})}
function factorial(n){if(!Number.isInteger(n)||n<0||n>170)throw 0;let r=1;for(let i=2;i<=n;i++)r*=i;return r}
function currentValue(){const safe=calcExpr.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').replaceAll('π',String(Math.PI)).replace(/\be\b/g,String(Math.E));if(!/^[0-9eE+\-*/().\s]+$/.test(safe))throw 0;return Function(`"use strict";return (${safe})`)()}
function unary(label,fn){const before=calcExpr,value=fn(Number(currentValue()));if(!Number.isFinite(value))throw 0;calcExpr=String(value);return `${label}(${before})`}
function deskKey(k){const display=$('deskDisplay');try{
 let historyExpression='';
 if(k==='MC'){memory=0;memorySet=false;memoryExpanded=false;memoryUserCollapsed=false}
 else if(k==='MR'){if(memorySet){calcExpr=String(memory);calcFreshInput=true}}
 else if(k==='M+'){memory+=Number(currentValue())||0;memorySet=true;if(!memoryUserCollapsed)memoryExpanded=true}
 else if(k==='M-'){memory-=Number(currentValue())||0;memorySet=true;if(!memoryUserCollapsed)memoryExpanded=true}
 else if(k==='C'){calcExpr='0';calcFreshInput=false}
 else if(k==='CE'){calcExpr=calcExpr.replace(/(?:\d*\.?\d+(?:e[+\-]?\d+)?)$/i,'')||'0';calcFreshInput=false}
 else if(k==='⌫'){calcExpr=calcExpr.length>1?calcExpr.slice(0,-1):'0';calcFreshInput=false}
 else if(k==='+/−')historyExpression=unary('neg',x=>-x);
 else if(k==='%')historyExpression=unary('%',x=>x/100);
 else if(k==='√')historyExpression=unary('√',Math.sqrt);
 else if(k==='x²')historyExpression=unary('sqr',x=>x*x);
 else if(k==='1/x')historyExpression=unary('recip',x=>1/x);
 else if(k==='n!')historyExpression=unary('fact',factorial);
 else if(k==='sin'||k==='cos'||k==='tan'){const f=Math[k],factor=angleUnit==='DEG'?Math.PI/180:1;historyExpression=unary(k,x=>f(x*factor))}
 else if(k==='asin'||k==='acos'||k==='atan'){const f=Math[k],factor=angleUnit==='DEG'?180/Math.PI:1;historyExpression=unary(k,x=>f(x)*factor)}
 else if(k==='ln')historyExpression=unary('ln',Math.log);
 else if(k==='log')historyExpression=unary('log',Math.log10);
 else if(k==='10ˣ')historyExpression=unary('10^',x=>10**x);
 else if(k==='π')calcExpr=calcExpr==='0'?String(Math.PI):calcExpr+String(Math.PI);
 else if(k==='e')calcExpr=calcExpr==='0'?String(Math.E):calcExpr+String(Math.E);
 else if(k==='xʸ')calcExpr+='^';
 else if(k==='EXP')calcExpr+='e';
 else if(k==='Ans'){const h=data.calcHistory||[];calcExpr=h.length?h[h.length-1].result:calcExpr}
 else if(k==='2nd'){}
 else if(k==='='){const expression=calcExpr.replaceAll('^','**'),safe=expression.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-');if(!/^[0-9eE+\-*/().\s*]+$/.test(safe))throw 0;const result=String(Function(`"use strict";return (${safe})`)());if(!Number.isFinite(Number(result)))throw 0;calcExpr=result;calcFreshInput=true;data.calcHistory=data.calcHistory||[];data.calcHistory.push({date:new Date().toISOString(),expression:`${expression} =`,result});data.calcHistory=data.calcHistory.slice(-100);save();renderCalcHistory()}
 else{if(k==='duplicate-zero')return;const next=applyCalculatorEntry(calcExpr,k,calcFreshInput);calcExpr=next.expr;calcFreshInput=next.freshInput}
 if(historyExpression){data.calcHistory=data.calcHistory||[];data.calcHistory.push({date:new Date().toISOString(),expression:`${historyExpression} =`,result:calcExpr});data.calcHistory=data.calcHistory.slice(-100);save();renderCalcHistory()}
 display.textContent=calcExpr;renderMemoryDisplay()
 }catch{display.textContent='Error';renderMemoryDisplay()}
}
async function registerDeviceUnlock(){if(!window.PublicKeyCredential)return toast(tr('deviceUnlockUnavailable'));try{if(data.settings.deviceCredentialId){data.settings.deviceCredentialId='';save();renderSettings();return}const challenge=crypto.getRandomValues(new Uint8Array(32)),userId=crypto.getRandomValues(new Uint8Array(16));const cred=await navigator.credentials.create({publicKey:{challenge,rp:{name:'Belt Roll Calculator'},user:{id:userId,name:'Raymond',displayName:'Raymond'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',userVerification:'required'},timeout:60000,attestation:'none'}});data.settings.deviceCredentialId=cred.id;save();renderSettings();toast(tr('deviceUnlockReady'))}catch{toast(tr('deviceUnlockFailed'))}}

